/*---
description: Unicode flags fold supplementary osage letters as code points.
features: [ts-unicode-regexp, ts-unicode-sequences, ts-strings, ts-arrays, ts-iteration, ts-tuples]
---*/
// Generated by tooling/unicode-cases/regexp.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, The design and Staying identical to node.
// Context: legacy i compares UTF-16 units while iu and iv fold the supplementary letter.
const pattern0 = /^\ud801\udcb0$/i;
const pattern1 = /^\ud801\udcb0$/iu;
const pattern2 = /^\ud801\udcb0$/iv;
const samples: [string, boolean, boolean, boolean][] = [
  ["\ud801\udcb0", true, true, true],
  ["\ud801\udcd8", false, true, true],
  ["\ud801\udcb0\ud801\udcd8", false, false, false],
  ["\ud800", false, false, false],
  ["\udc00", false, false, false],
];
for (const sample of samples) {
  assert.sameValue(pattern0.test(sample[0]), sample[1], "osage-supplementary-fold pattern 0");
  assert.sameValue(pattern1.test(sample[0]), sample[2], "osage-supplementary-fold pattern 1");
  assert.sameValue(pattern2.test(sample[0]), sample[3], "osage-supplementary-fold pattern 2");
}
